import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { API } from "../api/api";
import Navbar from "../components/Navbar";

export default function CreateSurvey() {
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState([]);
  const [visibleCount, setVisibleCount] = useState(4);

  const [title, setTitle] = useState("");
  const [category, setCategory] = useState("general");

  const nav = useNavigate();

  useEffect(() => {
    API.get("/questions").then((res) => setQuestions(res.data));
  }, []);

  const toggleSelect = (id) => {
    setSelected((prev) =>
      prev.includes(id)
        ? prev.filter((q) => q !== id)
        : [...prev, id]
    );
  };

  const createSurvey = async () => {
    try {
      if (!title) return alert("Enter title");
      if (selected.length === 0) return alert("Select questions");

      const selectedQuestions = questions
        .filter(q => selected.includes(q._id))
        .map(q => ({
          questionText: q.questionText,
          options: (q.options && q.options.length > 0)
            ? q.options.map(opt => ({ text: opt.text }))
            : [{ text: "Yes" }, { text: "No" }]
        }));

      await API.post("/surveys", {
        title,
        category,
        questions: selectedQuestions
      });

      alert("Survey Created 🚀");
      nav("/home");

    } catch (err) {
      console.log(err);
      alert("Error creating survey");
    }
  };

  const loadMore = () => {
    setVisibleCount((prev) => prev + 4);
  };

  return (
    <>
      <Navbar />

      <div className="survey-page">
        <h2>Create Survey 🧠</h2>

        <input
          placeholder="Survey Title"
          onChange={(e) => setTitle(e.target.value)}
        />

        <select onChange={(e) => setCategory(e.target.value)}>
          <option value="general">General</option>
          <option value="student">Student</option>
          <option value="teacher">Teacher</option>
        </select>

        {questions.slice(0, visibleCount).map((q) => {
          const isSelected = selected.includes(q._id);

          return (
            <div
              key={q._id}
              onClick={() => toggleSelect(q._id)}
              style={{
                padding: "10px",
                margin: "10px",
                background: isSelected ? "#22c55e" : "#1f2937",
                cursor: "pointer"
              }}
            >
              {q.questionText}
            </div>
          );
        })}

        {visibleCount < questions.length && (
          <button onClick={loadMore}>Load More</button>
        )}

        <button onClick={createSurvey}>Create Survey 🚀</button>
      </div>
    </>
  );
}
